(window.IBALL_PERIODICAL_LIBRARY = window.IBALL_PERIODICAL_LIBRARY || {})["2026-07-14"] = {"meta":{"id":"2026-07-14","label":"2026 年 7 月 14 日","date":"2026-07-14","range":"","theme":"","themes":[],"sources":[],"title":"","titleZh":"","counts":{"article":0,"paragraph":0,"vocab":0,"question":5,"qa":0,"original":2,"layout":1},"tabs":{"articles":false,"reading":false,"tests":true,"qa":false,"originals":true}},"articles":[],"reading":[],"tests":[{"file":"【福利】7.14检验题__阅读理解.docx","type":"reading","instructions":[],"passage":[],"items":[{"number":21,"stem":"Which of the following is NOT mentioned in Paragraph 2 as a factor driving the trend for salty drinks?","options":[{"key":"A","text":"A rising interest in premium salts"},{"key":"B","text":"The rehydrating effect of traditional street-corner drinks"},{"key":"C","text":"Government regulations requiring added salt in summer beverages"},{"key":"D","text":"A preference for savoury rather than sweet flavours"}],"answer":"C","kicker":"【答案】C","analysis":["【题型】细节理解题·排除题型","【难度】⭐⭐","【定位】Paragraph 2","【解析】","- 原文（Para.2）：\"Salty drinks traditionally sold on street corners in countries including India and Mexico can be rehydratating and are now being hailed as a salve in a heat-soaked UK. Factors driving the trend include a preference for savoury rather than sweet flavours and a rising interest in premium salts.\"","分析：","- 选项A：错误（非答案）。\"a rising interest in premium salts\"在原文中明确列为推动因素之一，故 A 项是原文提及的内容。","- 选项B：错误（非答案）。\"rehydratating\"（补充水分）是传统街角饮料的特性，原文明确提及，故 B 项是原文提及的内容。","- 选项C：正确（即NOT提及项）。题目要求选出\"NOT mentioned\"（未提及）的因素。原文列举的推动因素为\"a preference for savoury rather than sweet flavours\"和\"a rising interest in premium salts\"，从未提及\"Government regulations requiring added salt\"（政府法规要求在夏季饮料中加盐），C 项纯属无中生有，符合题意。","- 选项D：错误（非答案）。\"a preference for savoury rather than sweet flavours\"在原文中明确列出，故 D 项是原文提及的内容。"]},{"number":22,"stem":"It can be inferred from Malik-Flynn's comments in Paragraph 8 that the \"salty surge\" is partly driven by _____.","options":[{"key":"A","text":"a growing consumer rejection of pre-packaged syrups and artificial additives"},{"key":"B","text":"a sharp decline in the price of premium sea salt"},{"key":"C","text":"new scientific evidence proving that salt cures heatstroke"},{"key":"D","text":"a government campaign promoting salt intake during heatwaves"}],"answer":"A","kicker":"【答案】A","analysis":["【题型】推理判断题","【难度】⭐⭐⭐⭐","【定位】Paragraph 8","【解析】","- 原文（Para.8）：\"Malik-Flynn credits the salty surge to a wider shift away from sugar. 'Savoury flavours are big right now. People want freshness. They are becoming more aware of, and moving away from, drinks made from pre-packaged syrups and terrible modifiers filled with E-numbers,' he says.\"","分析：","- 选项A：正确。Malik-Flynn 将咸味饮料的兴起归因于\"wider shift away from sugar\"（远离糖的更广泛转变），并解释人们\"becoming more aware of, and moving away from, drinks made from pre-packaged syrups and terrible modifiers filled with E-numbers\"——越来越意识到并远离由预包装糖浆和充斥E编号（食品添加剂代号）的劣质调味剂制成的饮料。可推断出消费者对人工添加剂（artificial additives）的排斥推动了这一趋势，A 项精准概括其观点。","- 选项B：错误。使用了无中生有陷阱。原文从未提及\"sharp decline in the price of premium sea salt\"（优质海盐价格暴跌），价格因素并非 Malik-Flynn 论述的驱动力。","- 选项C：错误。使用了无中生有陷阱。原文讨论的是口味偏好和成分意识，从未提到\"salt cures heatstroke\"（盐治愈中暑）的科学研究，C 项捏造了科学依据。","- 选项D：错误。使用了无中生有陷阱。原文是市场自发趋势，并未提及\"government campaign\"（政府运动），D 项引入了原文不存在的主体。"]},{"number":23,"stem":"What function does the reference to The Devil Wears Prada 2 (Para.10) serve in the passage?","options":[{"key":"A","text":"To criticize the film industry for promoting unhealthy eating habits"},{"key":"B","text":"To illustrate how premium salt has become a status symbol in popular culture"},{"key":"C","text":"To argue that Maldon sea salt is superior to all other brands"},{"key":"D","text":"To show that salt consumption has reached dangerous levels among celebrities"}],"answer":"B","kicker":"【答案】B","analysis":["【题型】篇章结构题·段落功能","【难度】⭐⭐⭐","【定位】Paragraph 10","【解析】","- 原文（Para.9）：\"Similar to the fancification of olive oil, the humble mineral is experiencing its own glow-up. Forget a giant tub of fine Saxa pouring salt. Nowadays, aspiring chefs are more likely to spotlight designer boxes and beautiful jars...\"","- 原文（Para.10）：\"In The Devil Wears Prada 2, the product placement list included two boxes of Maldon sea salt flakes – somewhat bizarrely placed on the same kitchen countertop.\"","分析：","- 选项A：错误。使用了无中生有陷阱。原文仅提及该电影的产品植入，并未\"criticize the film industry for promoting unhealthy eating habits\"（批评电影业推广不健康饮食习惯），A 项捏造了批判态度。","- 选项B：正确。Para.9 论述盐正在经历\"glow-up\"（华丽转身），从廉价日用品升级为设计师级别的高端商品；Para.10 以《穿普拉达的女王2》中的产品植入为例，进一步说明高端盐（Maldon海盐）已成为流行文化中的地位象征（status symbol）。该例证服务于\"盐已成为高端消费品/身份象征\"这一论点，B 项精准概括其功能。","- 选项C：错误。使用了过度推理陷阱。原文提到 Maldon 海盐作为产品植入案例，但并未论证其\"superior to all other brands\"（优于所有其他品牌），C 项将该品牌的出现夸大为对品牌的绝对推崇。","- 选项D：错误。使用了无中生有陷阱。\"salt consumption has reached dangerous levels among celebrities\"（名人盐摄入量已达危险水平）与原文语境完全无关，原文讨论的是盐作为高端消费品的流行，而非健康危害。"]},{"number":24,"stem":"According to Lisa Harris (Para.14), premium salts appeal to consumers during economic uncertainty because _____.","options":[{"key":"A","text":"they are significantly cheaper than ordinary table salt"},{"key":"B","text":"they are exempt from the price inflation affecting other pantry goods"},{"key":"C","text":"a small amount offers an affordable form of everyday indulgence"},{"key":"D","text":"they provide essential minerals that people can no longer get from other foods"}],"answer":"C","kicker":"【答案】C","analysis":["【题型】推理判断题·人物观点归属","【难度】⭐⭐⭐⭐","【定位】Paragraph 14","【解析】","- 原文（Para.14）：\"'Premium salts certainly follow the trajectory of elevated pantry goods – which we've seen with olive oil, tinned fish and tinned beans,' says Lisa Harris, a co-founder of the food consultancy Harris and Hayes. 'In times of economic uncertainty, a pinch or a drizzle of something special feels like an achievable everyday indulgence.'\"","分析：","- 选项A：错误。使用了反义干扰陷阱。Harris 论述的是\"premium salts\"（优质盐）作为高端消费品，A 项\"significantly cheaper than ordinary table salt\"（比普通食盐便宜得多）与\"premium\"的高端定位完全相反。","- 选项B：错误。使用了无中生有陷阱。原文从未提及\"exempt from the price inflation\"（免受价格通胀影响），B 项引入了原文不存在的经济概念。","- 选项C：正确。Harris 明确说\"In times of economic uncertainty, a pinch or a drizzle of something special feels like an achievable everyday indulgence\"——在经济不确定时期，一撮或一点特别的东西感觉像是一种\"可实现\"的日常享受。这表明优质盐之所以在经济不景气时仍有吸引力，是因为少量即可提供\"affordable form of everyday indulgence\"（负担得起的日常享受），C 项精准概括其观点。","- 选项D：错误。使用了无中生有陷阱。\"provide essential minerals that people can no longer get from other foods\"（提供人们无法再从其他食物中获取的必需矿物质）是原文完全未涉及的营养学论述，Harris 讨论的是消费心理而非营养成分。"]},{"number":25,"stem":"The word \"glow-up\" (Para.9) is closest in meaning to _____.","options":[{"key":"A","text":"sudden disappearance"},{"key":"B","text":"gradual decline in quality"},{"key":"C","text":"temporary price reduction"},{"key":"D","text":"remarkable transformation or upgrade"}],"answer":"D","kicker":"【答案】D","analysis":["【题型】词义猜测题","【难度】⭐⭐⭐","【定位】Paragraph 9","【解析】","- 原文（Para.9）：\"Similar to the fancification of olive oil, the humble mineral is experiencing its own glow-up. Forget a giant tub of fine Saxa pouring salt. Nowadays, aspiring chefs are more likely to spotlight designer boxes and beautiful jars containing everything from rosy pink flakes to tiny grey grains.\"","分析：","- 选项A：错误。使用了反义干扰陷阱。\"sudden disappearance\"（突然消失）与原文矛盾——盐并非消失，而是被重新包装升级，A 项方向相反。","- 选项B：错误。使用了反义干扰陷阱。\"gradual decline in quality\"（质量逐渐下降）与原文相反，下文描述的是盐从廉价品升级为\"designer boxes and beautiful jars\"，说明质量在提升而非下降。","- 选项C：错误。使用了偷换概念陷阱。\"temporary price reduction\"（临时降价）将\"glow-up\"（华丽转身）偷换为价格下降，而原文讨论的是包装和定位的升级，且优质盐通常是提价而非降价，C 项概念错误。","- 选项D：正确。\"glow-up\"是现代俚语，意为\"外貌或形象的巨大改善、华丽转身\"。Para.9 上下文：\"the humble mineral is experiencing its own glow-up\"——这种卑微的矿物正在经历自己的\"glow-up\"；后文\"Similar to the fancification of olive oil\"（类似于橄榄油的精致化）和\"designer boxes and beautiful jars\"（设计师盒子和漂亮罐子）表明盐正从廉价日用品蜕变为高端消费品。D 项\"remarkable transformation or upgrade\"（显著的蜕变或升级）精准对应。","— — — — — — — — — —","本文档由我们自研的考研英语阅读理解大模型生成。该模型基于近10年考研英语真题进行训练。我们会根据同学们的反馈持续优化模型能力。","本文档为【福利】，不提供答疑服务，欢迎大家自行交流使用。","【两个常见问题】","随着AI技术的不断进步，通过知识投喂和持续训练，大模型已逐渐具备模仿真题命题风格的能力。这份文档正是这一尝试的成果。它仅作为福利提供给大家，起到辅助检验的作用。你可以根据自身需要选择使用，如果有所顾虑，完全可以不用。","如果对答案解析有疑惑，直接打开任何AI大模型（如Deepseek、Kimi等），上传该篇原文文档，然后复制粘贴对应的题目和选项，说清楚你的疑问，大模型会回应解释对应的问题。"]}]}],"qa":[],"originals":[{"kind":"test","label":"检验题","file":"【福利】7.14检验题__阅读理解.docx","ext":".docx","bytes":55400,"date":"2026-07-14","range":"","title":"","sourcePath":"D:\\外刊\\【福利】7.14检验题__阅读理解.docx","raw":".cache\\periodical-raw2"},{"kind":"layout","label":"杂志排版","file":"7.14排版.pdf","ext":".pdf","bytes":1005506,"date":"2026-07-14","range":"","title":"","sourcePath":"D:\\外刊\\7.14排版.pdf","raw":".cache\\periodical-raw2"}]};
